CV = 'Conhecimento e verdade'

DEBATES12 = [
dict(s='extincao-e-boa-existencia', n='Se tudo vai acabar, por que evitar a extinção?', t=TF, r='O Sol vai engolir a Terra e o universo esfria. Vale a pena gastar tanto com riscos existenciais, ou o que importa é a qualidade da existência enquanto ela dura?',
 v='A humanidade vai deixar de existir. Se nada mais acontecer, a Terra fica inabitável em cerca de um bilhão de anos e o Sol vira gigante vermelha em cinco; mais adiante, o universo esgota a energia útil. Diante disso, o esforço para evitar a extinção (os riscos X) parece adiar o inevitável. Uma crítica diz que o que importa não é durar, e sim que a existência, enquanto houver, seja boa: menos sofrimento, mais bem-estar. A outra posição responde que a diferença entre acabar neste século e acabar daqui a bilhões de anos é a maior diferença que existe.',
 lados=[('Evitar a extinção importa, mesmo que ela seja inevitável', ['O argumento vale para pessoas: todos morrem, e nem por isso a morte aos vinte é igual à morte aos noventa. A inevitabilidade do fim não apaga o valor do tempo entre agora e ele.', 'Escala: entre acabar em 2100 e acabar em um bilhão de anos cabem, em qualquer conta, mais vidas do que todas as que já existiram, e cada uma delas vale tanto quanto a nossa (Parfit, Bostrom, Ord). O que está em jogo não é adiar, é quase tudo.', 'O futuro é onde a boa existência pode acontecer: curar doenças, acabar com a criação industrial, reduzir o sofrimento dos animais selvagens, entender o universo. Extinguir-se agora é cancelar a possibilidade de fazer bem o que ainda fazemos mal.', 'Scheffler: muito do que dá sentido ao que fazemos hoje depende de que haja um depois coletivo; sem futuro, a pesquisa, a arte e a educação perdem parte do sentido já agora.']),
        ('O que importa é a boa existência, não a duração', ['Duração sem qualidade não vale: uma humanidade que dure um bilhão de anos repetindo guerras, criação industrial e miséria não é um bem a ser garantido; é um mal a ser evitado. Quem só conta vidas futuras esquece de perguntar como elas serão.', 'Assimetria: a ética focada no sofrimento e o utilitarismo negativo observam que evitar sofrimento é mais urgente do que criar felicidade; a extinção impede toda felicidade futura, mas também todo sofrimento futuro, e os riscos S (futuros de sofrimento astronômico) podem ser piores do que a extinção.', 'Custo de oportunidade: recursos e atenção gastos em riscos remotos e especulativos saem de quem sofre agora, com certeza e à vista; há uma vaidade em preferir salvar trilhões hipotéticos a milhões reais.', 'Humildade: não sabemos o que seres de daqui a mil anos vão valorizar, nem se nosso esforço muda algo nessa escala; agir bem no horizonte que entendemos é mais seguro do que apostar em cálculos astronômicos.'])],
 c=['A inevitabilidade não é argumento contra nenhum dos lados: ela só mostra que o que se disputa é o valor do tempo intermediário, e os dois lados admitem que ele tem valor.', 'A crítica da boa existência acerta num ponto que o longoprazismo maduro aceita: garantir a existência só vale se vier junto com o esforço para que ela seja boa, e o maior risco futuro pode ser o de sobreviver mal (riscos S), não o de não sobreviver. Reduzir riscos X e riscos S não compete; compete o que se prioriza quando o dinheiro é curto.', 'A crítica do custo de oportunidade é forte contra o excesso (gastar tudo em cenários especulativos) e fraca contra o essencial: pandemias planejadas, guerra nuclear e inteligências artificiais desalinhadas são riscos deste século, e reduzi-los também protege quem vive agora.', 'A escala que o primeiro lado invoca pressupõe que vidas futuras valem como as presentes; quem aceita isso para gerações próximas tem dificuldade em recusá-lo para as distantes.'],
 p=('parcial', 'O peso está com evitar a extinção, porque o fim inevitável não torna indiferente quando ele chega, e a diferença entre este século e os próximos bilhões de anos é a maior que a ética conhece. A crítica, porém, corrige o objetivo: o que vale a pena garantir não é a existência, e sim a boa existência, e um futuro longo de sofrimento pode ser pior do que nenhum futuro. A posição mais defendida junta as duas: reduzir os riscos de catástrofe deste século (que também ameaçam os vivos) e, com o mesmo empenho, reduzir o sofrimento presente e os riscos de futuros de sofrimento, sem deixar que a aposta em trilhões hipotéticos retire recursos de quem sofre agora.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'Cada vida futura conta como a nossa; a extinção cancela quase todo o valor possível.'), ('etica-focada-no-sofrimento', 'Foco no sofrimento', 'A prioridade é evitar sofrimento; a sobrevivência só vale se a existência for boa.'), ('utilitarismo-negativo', 'Utilitarismo negativo', 'Impedir o sofrimento futuro pesa mais do que criar felicidade futura; os riscos S preocupam mais do que os riscos X.'), ('temporalismo', 'Temporalismo', 'A distância no tempo não reduz o valor de quem vai existir.'), ('existencialismo', 'Existencialismo', 'O sentido não vem da duração cósmica; vem do que se faz com o tempo que há.'), ('epicurismo', 'Epicurismo', 'A extinção não é um mal para quem não vai existir; o mal está só no que se sofre antes.')],
 licoes=['riscos-s-e-riscos-x', 'geracoes-futuras', 'catastrofes-morais', 'o-peso-do-sofrimento', 'sentido-da-vida', 'etica-populacional'],
 fx=[('Existential risk (Wikipédia)', WE + 'Global_catastrophic_risk'), ('Death and the Afterlife', 'https://www.google.com/search?tbm=bks&q=Samuel+Scheffler+Death+and+the+Afterlife'), ('The Precipice', 'https://www.google.com/search?tbm=bks&q=Toby+Ord+The+Precipice'), ('Suffering-Focused Ethics', 'https://www.google.com/search?tbm=bks&q=Magnus+Vinding+Suffering-Focused+Ethics'), ('Future of Earth (Wikipédia)', WE + 'Future_of_Earth')]),

dict(s='limites-do-humor', n='Humor depreciativo, humor negro e os limites do humor', t=CO, r='“É só uma piada.” Quando o riso fere, quando é remédio, e por que “para cima” e “para baixo” não são a mesma coisa. O que a ética e a filosofia do humor dizem.',
 v='O humor negro ri da morte, da doença e da tragédia; o humor depreciativo ri de um grupo (etnia, gênero, deficiência, religião). Os dois são defendidos com a mesma frase, “é só uma piada”, e atacados com a mesma, “isso não tem graça”. A filosofia do humor tem três teorias do riso (superioridade, alívio, incongruência) e uma pergunta ética: pode uma piada ser engraçada e errada ao mesmo tempo, e quando dizer ou rir dela é uma falha moral?',
 lados=[('Em defesa do humor sem limites', ['A piada não é uma asserção: quem conta uma piada sobre um grupo não afirma nada sobre ele; o humor vive de fingimento e de incongruência, e tratá-lo como declaração é não entender o gênero.', 'Função: o humor negro é como as pessoas lidam com o que não controlam (médicos, soldados, enlutados riem do pior); proibi-lo tira um remédio.', 'Liberdade: o humor é a primeira vítima de todo regime que decide o que pode ser dito, e o ofendido não é juiz do que os outros podem rir.', 'O riso desarma: a sátira do poderoso e a piada sobre o próprio grupo mostram que rir pode ser forma de resistência e de pertencimento.']),
        ('O humor tem limites morais', ['Rir pressupõe atitudes: para achar graça numa piada que depende de que um grupo seja desprezível, é preciso, ao menos por um instante, adotar o desprezo (Ronald de Sousa). A piada não afirma, mas convida a partilhar uma atitude, e aceitar o convite é um ato.', 'Efeitos: o humor depreciativo, em ambientes onde o preconceito já existe, libera e normaliza (a “teoria da norma de preconceito”, com evidência experimental); e a vítima do grupo não escolhe participar do jogo.', 'Para cima e para baixo: rir de quem tem poder não é rir de quem não tem; a mesma estrutura de piada fere diferente conforme a posição de quem conta e de quem ouve.', 'O contexto decide: a piada de médico na sala dos médicos e a mesma piada diante da família do paciente não são o mesmo ato.'])],
 c=['A distinção central é entre o conteúdo (de que a piada ri) e a atitude (o que ela pede que se sinta): humor negro ri da tragédia sem exigir desprezo por ninguém; humor depreciativo depende do desprezo por um grupo para funcionar. É por isso que o primeiro é defensável quase sempre e o segundo, raramente.', 'Pode haver piada engraçada e errada: a graça é uma propriedade da incongruência, e o erro é uma propriedade da atitude e do efeito. Reconhecer a graça não absolve; negar a graça não é necessário para condenar.', '“É só uma piada” é verdadeiro contra quem trata a piada como asserção, e falso contra quem aponta o que ela pede que se sinta e o que ela faz no ambiente.', 'A resposta correta ao humor ruim raramente é a proibição; é não rir, dizer por que, e lembrar que o comediante responde pelo que faz com a plateia, como qualquer um.'],
 p=('parcial', 'O peso está com a existência de limites morais, mas traçados com precisão: o humor negro, que ri da tragédia sem pedir desprezo por quem a sofre, é legítimo e muitas vezes saudável; o humor depreciativo, que só funciona se o ouvinte aceitar que um grupo é inferior, convida a uma atitude que é errada fora da piada e não deixa de sê-lo dentro dela, sobretudo quando mira quem já está embaixo. A defesa da liberdade do humor acerta ao recusar a proibição e ao lembrar que ofensa não é critério; a resposta ao humor ruim é a mesma do mau argumento: não aderir, e dizer por quê.'),
 teorias=[('etica-das-virtudes', 'Virtudes', 'Aristóteles tinha uma virtude para isso, a eutrapelia: o humor entre o bufão e o rabugento; o virtuoso sabe de que rir e diante de quem.'), ('deontologia-kantiana', 'Kant', 'A piada que trata um grupo como desprezível desrespeita pessoas, tenha ou não efeito.'), ('utilitarismo-classico', 'Utilitarismo', 'Julgue pelo saldo: alívio e laço contra humilhação e normalização do preconceito; o contexto muda a conta.'), ('contratualismo-escanloniano', 'Scanlon', 'Quem é alvo poderia rejeitar razoavelmente um princípio que permita rir dele por ser quem é.'), ('sentimentalismo-moral', 'Sentimentalismo', 'O espectador imparcial ri com a sátira e não ri do desprezo; o riso é um juízo.')],
 licoes=['emocoes-morais', 'dilemas-do-cotidiano', 'igualdade-humana', 'como-discutir-etica', 'tribalismo-moral'],
 fx=[('Philosophy of Humor (Stanford Encyclopedia)', SEP + 'humor/'), ('Jokes: Philosophical Thoughts on Laughing Matters', 'https://www.google.com/search?tbm=bks&q=Ted+Cohen+Jokes+Philosophical+Thoughts+on+Laughing+Matters'), ('Theories of humor (Wikipédia)', WE + 'Theories_of_humor'), ('Black comedy (Wikipédia)', WE + 'Black_comedy'), ('Ethnic joke (Wikipédia)', WE + 'Ethnic_joke')]),

dict(s='poder-e-responsabilidade', n='Com grande poder vem grande responsabilidade?', t=JE, r='Governantes, empresários, cientistas, influenciadores, países ricos. A responsabilidade cresce com o poder, ou cada um responde só pelo que faz? O que a frase significa e o que ela esconde.',
 v='A frase é de quadrinhos, mas a ideia é antiga: quem pode mais deve mais. Ela aparece na parábola dos talentos, na noblesse oblige, em Rawls e no altruísmo eficaz. A pergunta tem duas partes: o poder cria deveres positivos (de usar o poder para o bem), e não só negativos (de não abusar)? E quem tem poder responde mais pelo mesmo erro do que quem não tem?',
 lados=[('O poder cria deveres proporcionais', ['Capacidade gera dever: quem pode salvar com pouco custo e não salva faz algo errado (a criança no lago); quem pode salvar milhares, com o que tem, deve ainda mais. O dever de beneficência cresce com o que se pode.', 'Quem decide por outros responde pelo que decide: o governante, o executivo e o médico tomam decisões cujas consequências recaem sobre quem não escolheu; essa assimetria é a fonte da responsabilidade.', 'Posição injusta: o poder raramente foi conquistado só com mérito; herança, sorte e estrutura o distribuem. Usar parte dele para corrigir o que o produziu é devolver, não doar.', 'Exemplo e norma: quem tem poder define o que é normal; o erro do poderoso ensina, o do fraco só acontece.']),
        ('A responsabilidade é pelo que se faz, não pelo que se pode', ['Deveres negativos são iguais para todos: não roubar, não mentir, não ferir. Deveres positivos proporcionais ao poder não têm limite claro e levam à exigência infinita, a objeção clássica ao consequencialismo.', 'Perigo do “dever de usar o poder”: foi a justificativa de impérios, intervenções e tutelas; quem acha que deve agir porque pode tende a agir sobre os outros sem lhes perguntar.', 'Igualdade perante a culpa: punir mais o poderoso pelo mesmo ato parece justiça, mas a pena deve seguir o ato e a intenção, não a posição; a posição entra na prevenção (quem pode mais, mais se vigia), não no merecimento.', 'Nem todo poder é escolhido: o cientista que descobre algo perigoso ou o herdeiro não pediram a posição; o dever de quem não escolheu é menor do que o de quem buscou.'])],
 c=['A frase é verdadeira em dois sentidos e falsa num terceiro: o poder aumenta o dever de cuidado (quem pode causar mais dano deve mais cautela) e o dever de beneficência (quem pode fazer mais bem a baixo custo deve fazê-lo); não aumenta a culpa pelo mesmo ato com a mesma intenção, embora a tornar mais grave em efeitos.', 'O risco da tutela é real e tem resposta: o dever que o poder cria é, antes de tudo, o de não abusar e o de prestar contas; o de agir pelos outros vem com a condição de ouvi-los.', 'A objeção da exigência infinita atinge o dever de beneficência em geral, não sua proporcionalidade: se há um dever de ajudar, ele cresce com o que se pode, qualquer que seja o teto.', 'O caso mais claro está nos países: os ricos, que mais emitem e mais podem, devem mais na mudança climática e na pobreza global, e a quase totalidade dos filósofos concorda.'],
 p=('parcial', 'O peso está com a proporcionalidade: o poder aumenta o dever de cautela, porque o dano possível é maior, e o dever de beneficência, porque o bem possível custa menos a quem pode mais; e quem decide pelos outros responde pelo que decide. A crítica acerta em três limites: a culpa pelo mesmo ato não cresce com a posição; o “dever de agir” do poderoso precisa do consentimento de quem é afetado, sob pena de virar tutela; e a responsabilidade é menor para o poder que não se escolheu. A frase, portanto, vale como regra de cautela e de beneficência, e não como licença.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'Quem pode produzir mais bem deve produzi-lo; o dever é proporcional à capacidade.'), ('prioritarismo', 'Prioritarismo', 'Poder e riqueza concentram-se em quem já está bem; a prioridade de quem está pior obriga quem pode mais.'), ('contratualismo-rawlsiano', 'Rawls', 'Desigualdades de poder só se justificam se beneficiarem os que estão pior; o poder vem com essa condição.'), ('deontologia-kantiana', 'Kant', 'A beneficência é dever imperfeito para todos; o poder não muda o dever, muda o quanto cabe cumprir.'), ('deontologia-de-direitos', 'Direitos', 'Os deveres são negativos e iguais; o poderoso deve só o que todos devem.'), ('confucionismo', 'Confucionismo', 'O governante é modelo; sua virtude ordena a sociedade e sua falta a corrompe.')],
 licoes=['da-etica-a-politica', 'economia-politica-e-etica', 'responsabilidade-coletiva', 'pobreza-e-etica-global', 'quanto-a-moral-pode-exigir'],
 fx=[('With great power comes great responsibility (Wikipédia)', WE + 'With_great_power_comes_great_responsibility'), ('Noblesse oblige (Wikipédia)', WE + 'Noblesse_oblige'), ('Fome, Riqueza e Moralidade', 'https://www.google.com/search?tbm=bks&q=Peter+Singer+Famine+Affluence+and+Morality'), ('Climate Justice (Stanford Encyclopedia)', SEP + 'justice-climate/')]),

dict(s='humildade', n='Humildade: virtude, vício ou postura?', t=VP, r='Aristóteles a desprezava, o cristianismo a colocou no centro, Nietzsche a chamou de moral de escravos. O que a humildade é, quando é virtude e quando é falsa.',
 v='Humildade é ter uma visão correta de si, sem inflar nem diminuir, e agir de acordo: reconhecer limites, dar crédito, aceitar correção. Parece inofensiva, mas as tradições discordam: Aristóteles considerava a “pequenez de alma” um vício e admirava o magnânimo, que sabe que vale muito; o cristianismo fez da humildade a raiz das virtudes; Nietzsche viu nela a virtude de quem não pode ser outra coisa. A pergunta é se a humildade é uma virtude em si, uma postura útil ou uma renúncia disfarçada.',
 lados=[('A humildade é uma virtude', ['Verdade sobre si: o orgulho infla, a falsa modéstia diminui; a humildade é a avaliação correta, e a verdade sobre si é condição de toda decisão sensata.', 'Abertura: quem se acha pronto não aprende nem corrige; a humildade é a disposição que torna possível ouvir, mudar de ideia e reparar. Veja o debate sobre humildade intelectual.', 'Relações: a humildade reconhece a dependência de outros e o acaso na própria sorte; é a virtude que impede o mérito de virar desprezo.', 'Evidência: pessoas humildes são mais bem avaliadas como líderes, cooperam mais e lidam melhor com o erro, em estudos de psicologia da personalidade.']),
        ('A humildade pode ser vício ou máscara', ['Aristóteles: diminuir-se é tão falso quanto inflar-se; quem vale muito e age como se não valesse mente, e desperdiça o que deve. A virtude é a magnanimidade: saber o próprio valor e exigir o que lhe cabe.', 'Nietzsche: a humildade pregada aos fracos é a vingança dos que não podem agir; ela transforma a impotência em mérito e o ressentimento em virtude.', 'Falsa humildade: a postura humilde é fácil de fingir e rende crédito; o humilde ostensivo é um orgulhoso com melhor estratégia.', 'Humildade e injustiça: ensinar humildade a quem já é oprimido (mulheres, pobres, colonizados) serviu para mantê-los no lugar; para quem está embaixo, a virtude necessária pode ser a autoafirmação.'])],
 c=['A disputa se resolve em boa parte definindo: humildade como avaliação correta de si (sem inflar nem diminuir) é compatível com Aristóteles, que condenava os dois erros; humildade como diminuição de si é o que Aristóteles e Nietzsche atacam, e nenhum defensor sério da humildade a defende.', 'A crítica da injustiça é a mais forte: a mesma virtude pedida a quem tem poder (para que o use bem) e a quem não tem (para que não reclame) não é a mesma coisa; a humildade é virtude de quem pode cair no orgulho, e autoafirmação é a virtude de quem foi ensinado a se diminuir.', 'A postura humilde, separada da disposição, é teatro; mas a disposição sem a postura (humilde por dentro, arrogante no trato) também falha, porque a humildade é em parte sobre como se trata os outros.'],
 p=('parcial', 'O peso está com a humildade como virtude, entendida como avaliação correta de si somada à abertura à correção e ao reconhecimento do que se deve aos outros e à sorte; assim definida, ela não contradiz Aristóteles e responde a Nietzsche, porque não pede diminuição nem renúncia. As críticas acertam em dois pontos que a definição incorpora: a falsa humildade é um vício, não uma versão fraca da virtude; e a humildade é devida sobretudo por quem tem poder, enquanto a quem foi ensinado a se diminuir a virtude que falta pode ser a de afirmar o próprio valor.'),
 teorias=[('etica-das-virtudes', 'Virtudes', 'Entre a arrogância e a pequenez de alma; Aristóteles e a tradição cristã discordam sobre onde fica o meio.'), ('etica-budista', 'Budismo', 'O apego ao eu é a raiz do sofrimento; a humildade é ver que o eu é menos do que parece.'), ('confucionismo', 'Confucionismo', 'O cavalheiro é modesto e cede o lugar; a humildade é ritual que ordena as relações.'), ('deontologia-kantiana', 'Kant', 'Humildade é comparar-se com a lei moral, não com os outros; diante dela, todos ficam pequenos e iguais em dignidade.'), ('objetivismo-de-ayn-rand', 'Objetivismo (Rand)', 'A humildade é a virtude que o altruísmo exige para que você aceite servir; o orgulho racional é a resposta.'), ('etica-do-cuidado', 'Cuidado', 'Reconhecer a dependência de outros é o começo da ética; a humildade é essa consciência.')],
 licoes=['aristoteles-e-as-virtudes', 'emocoes-morais', 'educacao-moral', 'eticas-religiosas', 'etica-do-carater'],
 fx=[('Humility (Wikipédia)', WE + 'Humility'), ('Ética a Nicômaco', 'https://www.google.com/search?tbm=bks&q=Arist%C3%B3teles+%C3%89tica+a+Nic%C3%B4maco'), ('Genealogia da Moral', 'https://www.google.com/search?tbm=bks&q=Nietzsche+Genealogia+da+Moral')]),

dict(s='fins-e-meios', n='Os fins justificam os meios?', t=FE, r='Maquiavel, Trótski, Dewey e os deontologistas. A frase mais citada da ética, o que ela diz de verdade, e por que a resposta certa é “às vezes, e por isso quase nunca”.',
 v='A frase atribuída a Maquiavel (que não a escreveu assim) pergunta se um bom resultado torna aceitável qualquer meio. Posta assim, quase ninguém diz sim. Mas a versão séria é mais difícil: há meios que nenhum fim justifica, ou todo meio é aceitável desde que o fim seja bom o bastante e o meio seja o único? É o núcleo da disputa entre consequencialismo e deontologia, e o teste de toda política.',
 lados=[('Os fins justificam os meios (em alguma medida)', ['Só os fins podem justificar meios: um meio não é bom nem mau em si, é um ato que produz algo; perguntar se o fim justifica o meio é a única pergunta sensata sobre ele (Dewey). O que se discute é se este fim justifica este meio.', 'Toda ética admite isso em casos: mentir ao assassino, usar força para impedir um crime, quebrar uma promessa para salvar uma vida. Quem diz “nunca” precisa aceitar a catástrofe para não sujar as mãos.', 'Trótski: quem rejeita a frase costuma ter outro fim escondido (a própria pureza), e esse fim também é um fim; a questão é qual fim justifica qual meio, e por quem.', 'Na política, a recusa absoluta de meios impuros entrega o poder a quem não a tem (Weber: a ética da responsabilidade contra a ética da convicção).']),
        ('Há meios que nenhum fim justifica', ['Pessoas não são meios: usar alguém sem consentimento para um fim, por melhor que seja, é tratá-lo como coisa; é o que proíbe a segunda fórmula do imperativo categórico e o que o transplante involuntário mostra.', 'O fim raramente chega: os meios são certos e presentes; o fim é futuro e incerto. A história dos que mataram “por um mundo melhor” é a história de meios reais e fins que nunca vieram. Os meios moldam o fim: uma revolução feita com terror produz um Estado de terror.', 'Quem calcula se engana a favor de si: a conta de fins e meios é feita por quem quer usar o meio, e o viés motivado infla o fim e esconde o custo. Restrições fixas existem porque a conta não é confiável quando mais importa.', 'Reputação e confiança: uma sociedade em que todos aceitam violar regras por bons fins é uma em que ninguém pode confiar em regra alguma; a utilidade das restrições vem de serem respeitadas quando é tentador não respeitar.'])],
 c=['A frase é ambígua entre “só os fins justificam meios” (verdade quase trivial) e “qualquer meio é justificado por um fim bom o bastante” (falsa para quase todas as teorias). A disputa real é sobre o limiar: que tamanho de fim justifica que gravidade de meio.', 'As duas famílias convergem mais do que parece: a deontologia de limiar admite que a catástrofe vence a restrição; o consequencialismo de regras admite restrições quase absolutas porque a conta caso a caso é viciada. Entre as duas sobra pouco espaço, e nele está o debate.', 'O argumento mais forte contra a frase não é deontológico, é empírico: os fins são incertos e os meios moldam o que vem depois; por isso mesmo o consequencialista cuidadoso desconfia de meios ruins mais do que o adepto ingênuo da frase.', 'A ética da responsabilidade de Weber não autoriza meios ruins; exige assumir as consequências deles, inclusive a de que corrompem quem os usa.'],
 p=('parcial', 'O peso está com uma resposta em dois tempos: os fins são a única coisa que pode justificar meios, e por isso meios comuns (mentir ao assassino, usar força para impedir um crime) se justificam por fins graves; mas há meios que quase nenhum fim justifica, porque tratam pessoas como coisas, porque o fim é incerto e o meio é certo, e porque a conta é feita por quem tem interesse nela. A posição mais defendida, da deontologia de limiar ao consequencialismo de regras, é tratar as restrições como quase absolutas, cedendo só diante de catástrofe comprovada, e desconfiar de quem diz que o seu fim é a exceção.'),
 teorias=[('consequencialismo-de-ato', 'Consequencialismo de ato', 'Só o resultado justifica; o meio é parte da conta, e a conta decide.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'Regras quase absolutas, porque a conta caso a caso falha quando mais importa.'), ('deontologia-kantiana', 'Kant', 'Nunca use uma pessoa apenas como meio; o fim não redime o meio.'), ('deontologia-de-limiar', 'Deontologia de limiar', 'As restrições valem até o limiar da catástrofe; ali, o fim passa a justificar.'), ('deontologia-absolutista', 'Absolutismo', 'Alguns meios nunca; faça-se justiça, pereça o mundo.'), ('etica-das-virtudes', 'Virtudes', 'O meio revela e forma o caráter; quem usa meios vis se torna vil, seja qual for o fim.')],
 licoes=['consequencialismo', 'deontologia', 'direitos-e-limiares', 'intencao-e-previsao', 'catastrofes-morais', 'objecoes-ao-consequencialismo'],
 fx=[('Consequentialism (Stanford Encyclopedia)', SEP + 'consequentialism/'), ('Their Morals and Ours (Wikipédia)', WE + 'Their_Morals_and_Ours'), ('A Política como Vocação', 'https://www.google.com/search?tbm=bks&q=Max+Weber+A+Pol%C3%ADtica+como+Voca%C3%A7%C3%A3o'), ('O Príncipe', 'https://www.google.com/search?tbm=bks&q=Maquiavel+O+Pr%C3%ADncipe'), ('Dirty Hands (Stanford Encyclopedia)', SEP + 'dirty-hands/')]),

dict(s='humildade-intelectual', n='Humildade intelectual: dever de duvidar ou desculpa?', t=CV, r='Saber o que não se sabe, dar peso ao desacordo, mudar de ideia. Quando a humildade intelectual é uma virtude e quando vira relativismo ou paralisia.',
 v='Humildade intelectual é reconhecer os limites do próprio conhecimento e tratar as próprias crenças como revisáveis: admitir que se pode estar errado, dar peso à evidência contrária e ao desacordo de quem é tão informado quanto nós. É a virtude epistêmica mais discutida das últimas décadas, por causa da polarização e da desinformação. A pergunta é se ela é um dever, até onde vai, e se tem um lado ruim: a dúvida que serve para não decidir e a falsa equidistância que trata toda posição como igualmente incerta.',
 lados=[('A humildade intelectual é uma virtude e um dever', ['Calibração: a história das ideias é a história de certezas erradas; quem se dá conta disso dá a cada crença a confiança que a evidência permite, nem mais, nem menos. Isso é a definição de pensar bem.', 'Desacordo: quando alguém tão informado e tão honesto quanto você discorda, isso é evidência de que um de vocês errou, e não há razão para supor que foi o outro (conciliacionismo).', 'Antídoto: o raciocínio motivado, o tribalismo e as câmaras de eco vivem da certeza; a humildade é a disposição que os enfraquece, e a evidência mostra que pessoas intelectualmente humildes avaliam melhor a evidência e mudam de ideia quando devem.', 'Moral: tratar as próprias crenças como infalíveis é tratar quem discorda como tolo ou malicioso; a humildade intelectual é também uma forma de respeito.']),
        ('A humildade intelectual tem limites e abusos', ['Nem toda crença merece dúvida: a Terra é redonda, as vacinas funcionam, a escravidão era errada; ser “humilde” sobre isso não é virtude, é covardia ou pose. A humildade se deve à evidência, e a evidência às vezes é esmagadora.', 'Falsa equidistância: tratar duas posições como igualmente incertas quando a evidência pesa para um lado é um erro de calibração tanto quanto a arrogância; a imprensa que “ouve os dois lados” sobre o clima não é humilde, é enganosa.', 'Paralisia: quem duvida de tudo não decide nada, e não decidir também é decidir; a ação exige confiança suficiente, e a humildade sem coragem vira desculpa.', 'Assimetria: pedir humildade a quem tem razão e certeza a quem está errado é o padrão dos debates públicos; o humilde cede, o arrogante ocupa o espaço. A virtude precisa de firmeza para não ser explorada.'])],
 c=['A humildade intelectual bem definida já contém as respostas: ela pede confiança proporcional à evidência, o que inclui confiança alta quando a evidência é alta. Duvidar do que está provado não é humildade; é descalibração.', 'A objeção do desacordo (ceder a quem discorda) tem resposta no conciliacionismo moderado: dê peso ao desacordo de iguais, mas não a todo desacordo; quem discorda sem evidência não é um igual epistêmico naquela questão.', 'O par da humildade intelectual é a coragem intelectual: dizer o que a evidência mostra mesmo quando é impopular. Sem ela, a humildade vira conformismo; sem a humildade, a coragem vira teimosia. Veja o debate sobre humildade em geral.', 'Na vida prática, a virtude se mede por um hábito simples: perguntar “o que me faria mudar de ideia?”, e ter uma resposta.'],
 p=('parcial', 'O peso está com a humildade intelectual como virtude e como dever de quem influencia outros, entendida como calibração: confiança proporcional à evidência, peso ao desacordo de quem é igualmente informado e disposição real de mudar de ideia. Os críticos acertam em recusar as caricaturas: a dúvida sobre o que está provado, a equidistância entre posições que a evidência não iguala, e a dúvida que serve para não decidir não são humildade, são falhas que a própria virtude condena. A versão madura junta humildade e coragem intelectual, e tem um teste: saber o que faria você mudar de ideia.'),
 teorias=[('etica-das-virtudes', 'Virtudes', 'Humildade intelectual é uma virtude epistêmica entre a arrogância e a covardia, e exige a coragem como par.'), ('intuicionismo-moral', 'Intuicionismo', 'As intuições são evidência, mas revisável; a humildade é tratá-las assim.'), ('pragmatismo', 'Pragmatismo', 'Toda crença é hipótese sujeita ao teste da comunidade; a humildade é a atitude do investigador (Peirce).'), ('etica-do-discurso', 'Ética do discurso', 'O argumento só vale se quem o faz aceita ser refutado; a humildade é condição do diálogo.'), ('objetivismo-moral', 'Objetivismo moral', 'Há verdades morais; a humildade não é relativismo, é a consciência de que ainda podemos estar errados sobre elas.'), ('ceticismo-normativo', 'Ceticismo', 'Se nada se sabe ao certo, a humildade vira regra geral; o risco é que vire paralisia.')],
 licoes=['etica-da-crenca', 'epistemologia-moral', 'incerteza-moral', 'abertura-moral', 'vieses-morais', 'como-discutir-etica'],
 fx=[('Disagreement (Stanford Encyclopedia)', SEP + 'disagreement/'), ('Intellectual humility (Wikipédia)', WE + 'Intellectual_humility'), ('Virtue Epistemology (Stanford Encyclopedia)', SEP + 'epistemology-virtue/')]),
dict(s='tornar-ignorantes-famosos', n='Tornar ignorantes famosos é errado?', t=CV, r='Audiências, mídia e algoritmos dão palco a quem fala com segurança sobre o que não sabe. Isso faz mal à sociedade? De quem é a responsabilidade, e o que “ignorante” não pode significar.',
 v='Fama é um recurso social: quem a tem é ouvido, imitado e acreditado. Hoje ela é distribuída menos por mérito do que por atenção, e a atenção vai para quem fala alto e com certeza, saiba ou não do que fala. O resultado é conhecido: pessoas sem conhecimento sobre saúde, ciência, história ou economia opinando para milhões, e sendo recompensadas por isso. A pergunta é se tornar essas pessoas famosas (dar plataforma, compartilhar, entrevistar, premiar com engajamento) é moralmente errado, de quem é a responsabilidade, e como fazer a pergunta sem que ela vire desprezo por quem estudou pouco.',
 lados=[('É errado: a fama da ignorância confiante faz mal a todos', ['Fama confere credibilidade: o público transfere a confiança que tem na pessoa (carismática, engraçada, bem-sucedida em algo) para o que ela diz sobre tudo. Quem amplifica sabe disso e lucra com isso.', 'Dano mensurável: desinformação sobre vacinas, tratamentos e dietas vinda de famosos tem efeito documentado sobre comportamento; a confiança falsa em quem não sabe custa saúde e dinheiro a quem acreditou.', 'Poluição epistêmica: quando a certeza rende mais do que a competência, o incentivo para estudar antes de falar desaparece, e quem sabe passa a parecer hesitante ao lado de quem não sabe. A sociedade perde a capacidade de distinguir.', 'Responsabilidade distribuída: cada compartilhamento, entrevista e clique é um voto por quem merece ser ouvido. Mídia que convida o ignorante “para dar audiência” e plataformas que o recomendam por engajamento escolheram; e o público também.', 'O problema não é a origem da pessoa, é o que se premia: falar com segurança sobre o que não se sabe é uma falha de honestidade, e recompensá-la é cultivá-la.']),
        ('Ressalvas: o rótulo é perigoso e a fama não é concedida por ninguém', ['Quem decide quem é ignorante? A história do rótulo é a história de elites desqualificando quem não tem diploma; muita gente famosa sem formação diz coisas verdadeiras, e muitos especialistas disseram coisas falsas com fama intacta.', 'Fama é emergente: ninguém “torna” alguém famoso; milhões de escolhas pequenas o fazem, e tratar isso como um ato moral de alguém infla a responsabilidade de cada um.', 'Liberdade: o remédio contra a fala errada é mais fala e checagem, não controle de quem pode ter audiência; a tentação de filtrar “ignorantes” leva a filtrar discordantes.', 'Nem toda fama é sobre conhecimento: o cantor, o atleta e o humorista famosos por talento não intelectual não são um problema; o problema aparece só quando a fama é usada para opinar sobre o que afeta outros.', 'Os famosos “ignorantes” são sintoma, não causa: a confiança nas instituições caiu por erros delas, e o público procura quem pareça falar sem filtro. Culpar o mensageiro não recupera a confiança.'])],
 c=['A palavra decide o debate: “ignorante” não pode significar quem estudou pouco, e sim quem fala com segurança sobre o que não sabe. Com essa definição, a maioria das ressalvas cai, porque o problema deixa de ser a pessoa e passa a ser o ato (afirmar sem saber) e o que o premia.', 'A responsabilidade é distribuída, mas não é nula: quem tem mais alcance (mídia, plataformas, quem entrevista) responde mais, e o público responde pelo que compartilha. “Ninguém tornou famoso” é verdade para cada clique e falsa para o conjunto, como no caso dos torturadores inofensivos.', 'O limite entre fama por talento e fama por opinião é a chave prática: celebrar o atleta é inofensivo; dar-lhe palco para falar sobre vacinas, e apresentar isso como informação, não é. A responsabilidade é de quem transfere a plataforma de um domínio para o outro.', 'A ressalva da liberdade acerta contra a censura e erra como desculpa: não amplificar não é calar. Escolher quem entrevistar, recomendar e compartilhar é exercício de juízo, não restrição de direito.', 'A ressalva do sintoma é a mais forte: enquanto as instituições não recuperarem confiança com honestidade e correção, a audiência vai para quem parece sincero. O remédio inclui as duas pontas.'],
 p=('parcial', 'O peso está com dizer que é errado, com a definição certa: premiar com fama quem afirma com segurança o que não sabe, sobre temas que afetam outros, causa dano documentado e corrói o incentivo de saber antes de falar; e a responsabilidade existe em proporção ao alcance, de quem convida e recomenda a quem compartilha. As ressalvas corrigem o alvo: o problema nunca é a pessoa com pouca escola, e sim o ato de afirmar sem saber e o sistema que o recompensa; a fama por talento não intelectual é inofensiva até que vire plataforma de opinião; e a resposta certa não é controlar quem fala, e sim escolher quem se amplifica e recuperar a confiança no conhecimento com honestidade.'),
 teorias=[('consequencialismo-de-regras', 'Consequencialismo de regras', 'Julgue a prática: uma sociedade que premia a certeza sem competência decide pior; mude o que se recompenda.'), ('etica-das-virtudes', 'Virtudes', 'Falar só do que se sabe é honestidade intelectual; amplificar quem não a tem é cultivar o vício em escala.'), ('deontologia-kantiana', 'Kant', 'Apresentar como informação o que se sabe ser opinião sem base engana o público; quem dá o palco participa do engano.'), ('etica-do-discurso', 'Ética do discurso', 'O debate público só funciona se a credibilidade seguir as razões, não a audiência; a fama da ignorância inverte isso.'), ('intuicionismo-moral', 'Intuicionismo', 'A intuição de que é errado enganar quem confia não precisa de teoria; a fama só muda a escala.'), ('utilitarismo-classico', 'Utilitarismo', 'Some o dano: comportamentos de saúde, decisões de voto e dinheiro perdido por quem acreditou, contra o entretenimento de quem assistiu.')],
 licoes=['etica-da-crenca', 'responsabilidade-coletiva', 'vieses-morais', 'tribalismo-moral', 'como-discutir-etica', 'etica-da-tecnologia'],
 fx=[('The Ethics of Belief (Stanford Encyclopedia)', SEP + 'ethics-belief/'), ('Dunning–Kruger effect (Wikipédia)', WE + 'Dunning%E2%80%93Kruger_effect'), ('Misinformation (Wikipédia)', WE + 'Misinformation'), ('Epistemic Injustice (Internet Encyclopedia of Philosophy)', 'https://iep.utm.edu/epistemic-injustice/'), ('Social Epistemology (Stanford Encyclopedia)', SEP + 'epistemology-social/')]),
]
assert len({d['s'] for d in DEBATES12}) == len(DEBATES12)
